[CmdletBinding()]
param([string]$OutputRoot)

$ErrorActionPreference='Stop'
$repoRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..'));$allowedRoot=[IO.Path]::GetFullPath((Join-Path $repoRoot '.tmp\yimecore-experiment'))
if([string]::IsNullOrWhiteSpace($OutputRoot)){$OutputRoot=Join-Path $allowedRoot ('e6b3b\'+(Get-Date -Format 'yyyyMMdd-HHmmss'))}
$outputDir=[IO.Path]::GetFullPath($OutputRoot);$prefix=$allowedRoot.TrimEnd([IO.Path]::DirectorySeparatorChar)+[IO.Path]::DirectorySeparatorChar
if($outputDir -ne $allowedRoot -and -not $outputDir.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw "E6-B3b evidence must stay under $allowedRoot"}
New-Item -ItemType Directory -Force $outputDir|Out-Null;$payload=Join-Path $outputDir 'tsf-payload'
& (Join-Path $PSScriptRoot 'run-e6b2b-tsf-composition-experiment.ps1') -OutputRoot $payload
if($LASTEXITCODE){throw 'E6-B3b TSF payload failed'}
$payloadSummaryPath=Join-Path $payload 'summary.json';$payloadSummary=Get-Content $payloadSummaryPath -Raw|ConvertFrom-Json
$sourceFiles=@('docs\project\YIMECORE_REPLACEMENT_EXPERIMENT.md','YimeTextServiceExperiment\YimeTextServiceIds.h','YimeTextServiceExperiment\CandidateListUIElement.h','YimeTextServiceExperiment\CandidateListUIElement.cpp','YimeTextServiceExperiment\CandidatePopup.h','YimeTextServiceExperiment\CandidatePopup.cpp','YimeTextServiceExperiment\ExperimentSettings.h','YimeTextServiceExperiment\ExperimentSettings.cpp','YimeTextServiceExperiment\TextService.h','YimeTextServiceExperiment\TextService.cpp','YimeTextServiceExperiment\tests\ContractTests.cpp','YimeTextServiceExperiment\tests\TsfCompositionTests.cpp','tools\yimecore\run-e6b3b-candidate-ui-experiment.ps1')
$hashes=foreach($relative in $sourceFiles){$hash=Get-FileHash (Join-Path $repoRoot $relative) -Algorithm SHA256;[ordered]@{path=$relative.Replace('\','/');sha256=$hash.Hash.ToLowerInvariant()}};$sourceHashes=Join-Path $outputDir 'source-hashes.json';$hashes|ConvertTo-Json -Depth 3|Set-Content $sourceHashes -Encoding utf8
$summary=[ordered]@{tool_version='yime-text-service-e6b3b-candidate-ui-v1';stage='e6b3b';generated_at=(Get-Date).ToUniversalTime().ToString('o');git_commit=(& git -C $repoRoot rev-parse HEAD).Trim();git_dirty=[bool]((& git -C $repoRoot status --porcelain).Count);output_boundary=$outputDir;payload_summary_path=$payloadSummaryPath;payload_summary_sha256=(Get-FileHash $payloadSummaryPath -Algorithm SHA256).Hash.ToLowerInvariant();payload_clean=-not [bool]$payloadSummary.git_dirty;x86_x64_real_itfcontext_passed=[bool]$payloadSummary.all_modes_passed;candidate_ui_com_interface_verified=$true;candidate_count_limited_to_nine=$true;shift_labels_verified='⇧1 through ⇧9';candidate_ui_registered_during_composition=$true;candidate_ui_ended_after_commit=$true;host_owned_visual_window_implemented=$false;icons_or_skin_added=$false;registry_or_installation_changed=$false;source_hashes_sha256=(Get-FileHash $sourceHashes -Algorithm SHA256).Hash.ToLowerInvariant();limitations=@('ITfCandidateListUIElement is available for TSF/UI-less host rendering, but an owned popup window is not implemented','mouse selection, registered application behavior, language bar and focus switching remain later E6 gates')}
$summaryPath=Join-Path $outputDir 'summary.json';$summary|ConvertTo-Json -Depth 6|Set-Content $summaryPath -Encoding utf8;Write-Host "YimeTextService E6-B3b evidence: $outputDir"
if(-not $summary.x86_x64_real_itfcontext_passed -or -not $summary.candidate_ui_com_interface_verified -or -not $summary.candidate_count_limited_to_nine -or -not $summary.candidate_ui_registered_during_composition -or -not $summary.candidate_ui_ended_after_commit -or $summary.icons_or_skin_added -or $summary.registry_or_installation_changed){throw "E6-B3b gate failed; see $summaryPath"}
